QUIZ_DATABASE["N2"]["dochieu"] = {"label": "Đọc Hiểu", "unitLabel": "unit", "slots": 13, "tests": {"1": {"title": "Unit 01 · 名詞A — Danh từ A — Đọc hiểu · Mimi kara Oboeru", "passage": "この 制度（せいど）は、年齢（ねんれい）を 問（と）わず 誰（だれ）でも 利用（りよう）できる。ただし、未成年者（みせいねんしゃ）を 除（のぞ）いては、保護者（ほごしゃ）の 同意（どうい）が必要（ひつよう）である。会員（かいいん）に 限（かぎ）っては、追加料金（ついかりょうきん）が かからない。", "questions": [{"q": "Ai có thể sử dụng chế độ này?", "options": ["Bất kể tuổi tác, ai cũng được", "Chỉ người trưởng thành", "Chỉ hội viên", "Chỉ học sinh"], "answer": 0, "explain": "「年齢を問わず誰でも利用できる」 — ～を問わず (Unit 01)."}, {"q": "Trường hợp ngoại lệ cần sự đồng ý của người bảo hộ là ai?", "options": ["Người cao tuổi", "Hội viên mới", "Người nước ngoài", "Người chưa thành niên"], "answer": 3, "explain": "「未成年者を除いては」 — ở đây cấu trúc thông báo: riêng người chưa thành niên (ngoại lệ) thì cần đồng ý của phụ huynh."}, {"q": "Ai không phải trả phí thêm?", "options": ["Trẻ em", "Người cao tuổi", "Chỉ hội viên", "Tất cả mọi người"], "answer": 2, "explain": "「会員に限っては、追加料金がかからない」 — ～に限って."}, {"q": "Ba mẫu を問わず・を除いて・に限って lần lượt diễn tả gì?", "options": ["Bất kể / ngoại trừ / chỉ giới hạn ở", "Ngoại trừ / chỉ giới hạn / bất kể", "Cả ba đều là 'bất kể'", "Chỉ giới hạn / bất kể / ngoại trừ"], "answer": 0, "explain": "Đây là ba mẫu phạm vi kinh điển của N2."}]}, "2": {"title": "Unit 02 · 動詞A — Động từ A — Đọc hiểu · Mimi kara Oboeru", "passage": "このまま 対策（たいさく）を 講（こう）じなければ、事故（じこ）が 起（お）きかねない。担当者（たんとうしゃ）は 詳細（しょうさい）を 申（もう）し上（あ）げかねる 様子（ようす）だった。彼（かれ）の 苦労（くろう）は、言葉（ことば）では 言（い）い表（あらわ）しがたい。", "questions": [{"q": "Nếu không có biện pháp, điều gì có thể xảy ra?", "options": ["Nhân viên nghỉ việc", "Công ty phá sản ngay", "Tai nạn có thể xảy ra", "Dự án bị hủy chắc chắn"], "answer": 2, "explain": "「事故が起きかねない」 — ～かねない = có khả năng xấu."}, {"q": "Người phụ trách tỏ vẻ thế nào về chi tiết vụ việc?", "options": ["Từ chối trả lời vì bận", "Đã nói hết", "Rất muốn nói ngay", "Khó nói / không thể trình bày"], "answer": 3, "explain": "「申し上げかねる様子」 — ～かねる = không thể (vì khó xử/lịch sự)."}, {"q": "Nỗi vất vả của anh ấy được mô tả thế nào?", "options": ["Khó diễn tả bằng lời", "Không đáng kể", "Đã qua lâu rồi", "Ai cũng hiểu ngay"], "answer": 0, "explain": "「言葉では言い表しがたい」 — ～がたい = khó mà."}, {"q": "～かねない và ～かねる khác nhau thế nào?", "options": ["かねる = có thể xảy ra; かねない = không thể", "Hoàn toàn giống nhau", "Cả hai đều tích cực", "かねない = có thể xảy ra (điều xấu); かねる = không thể làm (vì tâm lý/lịch sự)"], "answer": 3, "explain": "Cặp mẫu dễ nhầm nhất ở nhóm khả năng N2."}]}, "3": {"title": "Unit 03 · 形容詞A — Tính từ A — Đọc hiểu · Mimi kara Oboeru", "passage": "彼（かれ）は 忙（いそが）しい ばかりか、疲（つか）れても いるようだ。手伝（てつだ）う どころか、かえって 邪魔（じゃま）を して しまった。専門家（せんもんか）でさえ 解（と）けない 問題（もんだい）を、彼（かれ）は 一人（ひとり）で 考（かんが）え 続（つづ）けた。", "questions": [{"q": "Tình trạng của anh ấy gồm những gì?", "options": ["Không bận lắm", "Chỉ bận một chút", "Không chỉ bận mà còn mệt", "Bận nhưng rất khỏe"], "answer": 2, "explain": "「忙しいばかりか、疲れてもいる」 — ～ばかりか."}, {"q": "Anh ta đã làm gì thay vì giúp đỡ?", "options": ["Ngược lại còn gây cản trở", "Đứng nhìn im lặng", "Đi gọi người khác", "Giúp được rất nhiều"], "answer": 0, "explain": "「手伝うどころか、かえって邪魔をしてしまった」 — ～どころか."}, {"q": "Bài toán được mô tả khó đến mức nào?", "options": ["Học sinh cũng giải được", "Ngay cả chuyên gia cũng không giải được", "Chưa ai thử giải", "Chỉ cần thêm thời gian"], "answer": 1, "explain": "「専門家でさえ解けない問題」 — ～でさえ."}, {"q": "Ba mẫu ばかりか・どころか・でさえ đều có điểm chung gì?", "options": ["Chỉ thời gian", "Chỉ điều kiện cần", "Nhấn mạnh mức độ vượt ngoài dự đoán", "Chỉ nguyên nhân khách quan"], "answer": 2, "explain": "Nhóm mẫu nhấn mạnh mức độ của Unit 03 N2."}]}, "4": {"title": "Unit 04 · 名詞B — Danh từ B — Đọc hiểu · Mimi kara Oboeru", "passage": "調査結果（ちょうさけっか）に 基（もと）づいて、改善策（かいぜんさく）が 立（た）てられた。新事業（しんじぎょう）を 始（はじ）めるに あたって、市場（しじょう）の 動向（どうこう）が 詳（くわ）しく 分析（ぶんせき）された。訓練（くんれん）は 専門家（せんもんか）の 指導（しどう）のもとで 行（おこな）われた。", "questions": [{"q": "Phương án cải thiện được lập dựa trên gì?", "options": ["Kết quả điều tra", "Kinh nghiệm năm ngoái", "Ý kiến cá nhân giám đốc", "Báo cáo nước ngoài"], "answer": 0, "explain": "「調査結果に基づいて」 — ～に基づいて."}, {"q": "Trước khi bắt đầu dự án mới, việc gì được thực hiện kỹ lưỡng?", "options": ["Phân tích xu hướng thị trường", "Xây văn phòng", "Tuyển dụng nhân viên", "Quảng cáo sản phẩm"], "answer": 0, "explain": "「新事業を始めるにあたって、市場の動向が詳しく分析された」."}, {"q": "Buổi huấn luyện diễn ra dưới sự hướng dẫn của ai?", "options": ["Giảng viên nội bộ", "Trưởng phòng", "Giám đốc", "Chuyên gia"], "answer": 3, "explain": "「専門家の指導のもとで」 — ～のもとで."}, {"q": "～にあたって trong đoạn có nghĩa là gì?", "options": ["Dựa trên căn cứ", "Dưới sự bảo trợ", "Nhân dịp/khi bắt đầu một việc quan trọng", "Theo đúng kế hoạch"], "answer": 2, "explain": "始めるにあたって = khi/vào dịp bắt đầu (việc quan trọng)."}]}, "5": {"title": "Unit 05 · カタカナA — Từ Katakana A — Đọc hiểu · Mimi kara Oboeru", "passage": "この 施設（しせつ）は １時間（じかん）あたり ５００円（えん）で 利用（りよう）できる。電車（でんしゃ）は １０分（ぷん）ごとに １本（ぽん）来（く）る。彼（かれ）とは ５年（ねん）ぶりに 再会（さいかい）し、駅（えき）から 海岸（かいがん）に かけての 道（みち）を 懐（なつ）かしく 思（おも）い出（だ）した。", "questions": [{"q": "Giá sử dụng cơ sở này tính thế nào?", "options": ["500 yên mỗi ngày", "500 yên mỗi giờ", "500 yên mỗi lần", "500 yên mỗi người bất kể giờ"], "answer": 1, "explain": "「１時間あたり５００円」 — ～あたり."}, {"q": "Tàu điện chạy với tần suất nào?", "options": ["Cứ 10 phút một chuyến", "Cứ 5 phút một chuyến", "Cách 10 phút mới có (nhấn mạnh khoảng trống)", "Mỗi giờ một chuyến"], "answer": 0, "explain": "「１０分ごとに１本来る」 — ～ごとに = mỗi (đều đặn)."}, {"q": "Cuộc tái ngộ diễn ra sau bao lâu?", "options": ["Sau 10 năm", "Sau 5 năm", "Sau 1 năm", "Lần đầu tiên"], "answer": 1, "explain": "「５年ぶりに再会し」 — ～ぶりに = sau (khoảng thời gian)."}, {"q": "Cụm 駅から海岸にかけて chỉ điều gì?", "options": ["Số người đi cùng", "Khoảng không gian từ ga đến bờ biển", "Khoảng thời gian chờ đợi", "Chi phí di chuyển"], "answer": 1, "explain": "～にかけて = từ...đến... (phạm vi không gian/thời gian)."}]}, "6": {"title": "Unit 06 · 副詞A・接続詞 — Trạng từ A · Liên từ — Đọc hiểu · Mimi kara Oboeru", "passage": "努力（どりょく）した ものの、結果（けっか）は 思（おも）うように 出（で）なかった。体（からだ）に 悪（わる）いと 知（し）りつつ、彼（かれ）は タバコを やめられない。ベテランとはいえ、ミスを 完全（かんぜん）に なくすことは できない。", "questions": [{"q": "Kết quả của nỗ lực thế nào?", "options": ["Đang cải thiện dần", "Chưa có kết quả gì", "Không được như mong muốn", "Tốt ngoài mong đợi"], "answer": 2, "explain": "「努力したものの、結果は思うように出なかった」 — ～ものの."}, {"q": "Anh ấy không bỏ được thuốc mặc dù biết điều gì?", "options": ["Biết bị cấm", "Biết là tốn tiền", "Biết là hại sức khỏe", "Biết mọi người ghét"], "answer": 2, "explain": "「体に悪いと知りつつ」 — ～つつ (nhượng bộ)."}, {"q": "Ngay cả người kỳ cựu cũng không làm được điều gì?", "options": ["Làm việc nhanh hơn", "Nhớ mọi quy trình", "Dạy người mới", "Loại bỏ hoàn toàn sai sót"], "answer": 3, "explain": "「ベテランとはいえ、ミスを完全になくすことはできない」."}, {"q": "Ba mẫu ものの・つつ・とはいえ đều thuộc nhóm nào?", "options": ["Nhượng bộ (mặc dù...nhưng)", "Nguyên nhân tích cực", "Điều kiện cần thiết", "Thời gian đồng thời đơn thuần"], "answer": 0, "explain": "Cả ba đều là nhượng bộ văn viết của N2."}]}, "7": {"title": "Unit 07 · 名詞C — Danh từ C — Đọc hiểu · Mimi kara Oboeru", "passage": "環境問題（かんきょうもんだい）を めぐって、国際会議（こくさいかいぎ）で 活発（かっぱつ）な 議論（ぎろん）が 交（か）わされた。留学（りゅうがく）を きっかけに、彼（かれ）の 人生（じんせい）は 大（おお）きく 変（か）わった。その 日（ひ）を 境（さかい）に、彼（かれ）とは 連絡（れんらく）が 取（と）れなく なった。", "questions": [{"q": "Hội nghị quốc tế tranh luận xoay quanh vấn đề gì?", "options": ["Thương mại", "Giáo dục", "Vấn đề môi trường", "Năng lượng hạt nhân (không nói)"], "answer": 2, "explain": "「環境問題をめぐって」 — ～をめぐって."}, {"q": "Cuộc đời anh ấy thay đổi nhờ cơ duyên nào?", "options": ["Đổi việc", "Đi du học", "Kết hôn", "Gặp một người thầy"], "answer": 1, "explain": "「留学をきっかけに」 — ～をきっかけに."}, {"q": "Từ ngày đó trở đi, chuyện gì xảy ra?", "options": ["Anh ấy chuyển nhà gần hơn", "Không liên lạc được với anh ấy nữa", "Hai người thân thiết hơn", "Công việc thuận lợi hơn"], "answer": 1, "explain": "「その日を境に、連絡が取れなくなった」 — ～を境に (bước ngoặt)."}, {"q": "～をきっかけに và ～を境に khác nhau thế nào?", "options": ["境 = cơ duyên; きっかけ = mốc thời gian", "Hoàn toàn giống nhau", "Một cái dùng cho vật, một cái cho người", "きっかけ = cơ duyên bắt đầu thay đổi; 境 = mốc thời gian phân chia trước/sau"], "answer": 3, "explain": "Cặp mẫu mốc/cơ duyên dễ nhầm của N2."}]}, "8": {"title": "Unit 08 · 動詞B — Động từ B — Đọc hiểu · Mimi kara Oboeru", "passage": "不景気（ふけいき）で、倒産（とうさん）する 会社（かいしゃ）は 増（ふ）える 一方（いっぽう）だ。何度（なんど）も 練習（れんしゅう）した 末（すえ）に、彼（かれ）は ついに 優勝（ゆうしょう）した。朝食（ちょうしょく）ぬきで 出（で）かけたので、昼前（ひるまえ）には おなかが すいて しまった。", "questions": [{"q": "Số công ty phá sản thay đổi thế nào?", "options": ["Ngày càng giảm", "Ngày càng tăng", "Tăng rồi giảm", "Không đổi"], "answer": 1, "explain": "「増える一方だ」 — ～一方だ (xu hướng một chiều)."}, {"q": "Anh ấy vô địch sau quá trình nào?", "options": ["Luyện tập rất nhiều lần", "Đối thủ bỏ cuộc", "Được đặc cách", "Thi đấu may mắn"], "answer": 0, "explain": "「何度も練習した末に」 — ～た末に (sau nỗ lực dài)."}, {"q": "Vì sao trước trưa đã đói?", "options": ["Tập thể thao buổi sáng", "Thức khuya", "Ra ngoài mà không ăn sáng", "Ăn sáng quá ít"], "answer": 2, "explain": "「朝食ぬきで出かけた」 — ～ぬきで (mà không có)."}, {"q": "～あげく khác ～末に ở sắc thái nào (theo chương trình N2)?", "options": ["あげく thường dẫn đến kết quả tiêu cực/đáng tiếc; 末に trung tính hoặc tích cực sau nỗ lực", "末に luôn tiêu cực", "あげく luôn tích cực", "Không khác gì nhau"], "answer": 0, "explain": "Phân biệt cặp mẫu 'cuối cùng' — あげく mang sắc thái hối tiếc."}]}, "9": {"title": "Unit 09 · カタカナB — Từ Katakana B — Đọc hiểu · Mimi kara Oboeru", "passage": "新製品（しんせいひん）の 発表（はっぴょう）に 先立（さきだ）って、アンケート調査（ちょうさ）が 行（おこな）われた。長（なが）い 討論（とうろん）を 経（へ）て、計画（けいかく）は 承認（しょうにん）された。第一部（だいいちぶ）に 続（つづ）いて、第二部（だいにぶ）の 発表（はっぴょう）が 始（はじ）まった。", "questions": [{"q": "Khảo sát ý kiến được thực hiện khi nào?", "options": ["Trong lễ ra mắt", "Trước khi công bố sản phẩm mới", "Một tháng sau", "Sau khi bán sản phẩm"], "answer": 1, "explain": "「発表に先立って、アンケート調査が行われた」 — ～に先立って."}, {"q": "Kế hoạch được phê duyệt sau quá trình nào?", "options": ["Thử nghiệm 1 năm", "Thảo luận dài", "Bỏ phiếu nhanh", "Đàm phán với đối tác"], "answer": 1, "explain": "「長い討論を経て」 — ～を経て (trải qua)."}, {"q": "Phần hai bắt đầu như thế nào so với phần một?", "options": ["Trước phần một", "Tiếp nối ngay sau phần một", "Bị hủy", "Đồng thời với phần một"], "answer": 1, "explain": "「第一部に続いて、第二部が始まった」 — ～に続いて."}, {"q": "～に先立って và ～に続いて quan hệ thế nào?", "options": ["Không liên quan đến thứ tự", "Cả hai đều là 'sau'", "Cả hai đều là 'trước'", "Một mẫu là 'trước sự kiện', mẫu kia là 'tiếp nối sau sự kiện'"], "answer": 3, "explain": "Cặp mẫu trình tự trang trọng đối lập nhau."}]}, "10": {"title": "Unit 10 · 形容詞B — Tính từ B — Đọc hiểu · Mimi kara Oboeru", "passage": "彼（かれ）は 疲（つか）れげな 顔（かお）で 会議室（かいぎしつ）を 出（で）て きた。その やり方（かた）は 素人（しろうと）じみて いて、プロの 目（め）には 危（あぶ）なっかしく 見（み）えた。彼女（かのじょ）は 細（こま）かい ことまで 心配（しんぱい）する きらいが ある。", "questions": [{"q": "Anh ấy rời phòng họp với vẻ mặt thế nào?", "options": ["Trông vui vẻ", "Trông bối rối", "Trông giận dữ", "Trông mệt mỏi"], "answer": 3, "explain": "「疲れげな顔」 — ～げ (vẻ bề ngoài)."}, {"q": "Cách làm của anh ta bị đánh giá thế nào?", "options": ["Đầy sáng tạo", "Trông nghiệp dư", "Quá cầu kỳ", "Rất chuyên nghiệp"], "answer": 1, "explain": "「素人じみている」 — ～じみた (có vẻ giống, tiêu cực)."}, {"q": "Cô ấy có khuynh hướng tính cách nào?", "options": ["Hay khoe khoang", "Hay nóng nảy", "Hay lo lắng đến từng chi tiết nhỏ", "Hay quên"], "answer": 2, "explain": "「心配するきらいがある」 — ～きらいがある (khuynh hướng tiêu cực, trang trọng)."}, {"q": "Ba mẫu げ・じみた・きらいがある đều dùng để làm gì?", "options": ["Chỉ thời gian và địa điểm", "Chỉ nguyên nhân khách quan", "Ra mệnh lệnh lịch sự", "Đánh giá vẻ ngoài / tính chất / khuynh hướng của người hoặc việc"], "answer": 3, "explain": "Nhóm mẫu đánh giá tính chất của Unit 10 N2."}]}, "11": {"title": "Unit 11 · 名詞D — Danh từ D — Đọc hiểu · Mimi kara Oboeru", "passage": "環境（かんきょう）に 関（かん）する 法律（ほうりつ）が 改正（かいせい）された。予想（よそう）に 反（はん）して、結果（けっか）は 惨敗（ざんぱい）だった。兄（あに）は 勉強家（べんきょうか）だ。それに ひきかえ、弟（おとうと）は 遊（あそ）んで ばかり いる。", "questions": [{"q": "Luật nào đã được sửa đổi?", "options": ["Luật giao thông", "Luật liên quan đến môi trường", "Luật lao động", "Luật thuế"], "answer": 1, "explain": "「環境に関する法律」 — ～に関する."}, {"q": "Kết quả thực tế so với dự đoán thế nào?", "options": ["Chưa có kết quả", "Trái ngược hoàn toàn — thua thảm hại", "Đúng như dự đoán", "Tốt hơn dự đoán"], "answer": 1, "explain": "「予想に反して、結果は惨敗だった」 — ～に反して."}, {"q": "Anh và em trai khác nhau thế nào?", "options": ["Cả hai đều ham chơi", "Anh ham chơi, em chăm học", "Anh chăm học, em chỉ toàn chơi", "Cả hai đều chăm"], "answer": 2, "explain": "「それにひきかえ」 — đối lập hai đối tượng."}, {"q": "～に関する và ～に反して khác nhau ở chức năng gì?", "options": ["Một cái dùng cho người, một cái cho vật", "Cả hai đều là 'trái với'", "に関する = liên quan đến (chủ đề); に反して = trái với (kỳ vọng/quy định)", "Cả hai đều là 'liên quan'"], "answer": 2, "explain": "Phân biệt hai mẫu Unit 11."}]}, "12": {"title": "Unit 12 · 動詞C — Động từ C — Đọc hiểu · Mimi kara Oboeru", "passage": "故郷（ふるさと）の 母（はは）の 声（こえ）を 聞（き）くと、懐（なつ）かしくて ならない。赤（あか）ちゃんの 笑顔（えがお）は かわいくて たまらない。平和（へいわ）への 祈（いの）りは、今（いま）も なお やまない。", "questions": [{"q": "Nghe giọng mẹ ở quê, người viết cảm thấy thế nào?", "options": ["Nhớ nhung vô cùng", "Lo lắng", "Không cảm xúc gì", "Buồn bã tuyệt vọng"], "answer": 0, "explain": "「懐かしくてならない」 — ～てならない (cảm xúc tự nhiên mạnh)."}, {"q": "Nụ cười em bé khiến người viết cảm thấy thế nào?", "options": ["Khó chịu", "Ngạc nhiên thoáng qua", "Dễ thương đến không chịu nổi", "Không ấn tượng"], "answer": 2, "explain": "「かわいくてたまらない」 — ～てたまらない."}, {"q": "Lời cầu nguyện hòa bình được mô tả thế nào?", "options": ["Đã kết thúc", "Mới bắt đầu", "Chỉ còn trong sách", "Vẫn không ngừng cho đến nay"], "answer": 3, "explain": "「祈りは今もなおやまない」 — ～やまない (không ngừng, trang trọng)."}, {"q": "Ba mẫu てならない・てたまらない・やまない đều diễn tả điều gì?", "options": ["Khả năng khách quan", "Cảm xúc/mong ước mạnh mẽ không kìm nén được hoặc không ngừng", "Sự cho phép", "Sự bắt buộc bên ngoài"], "answer": 1, "explain": "Nhóm mẫu cảm xúc cao trào của N2."}]}, "13": {"title": "Unit 13 · 副詞B・連体詞 — Trạng từ B · Định ngữ — Đọc hiểu · Mimi kara Oboeru", "passage": "あくまでも 最後（さいご）まで あきらめない。この 仕事（しごと）は せいぜい ３日（か）で 終（お）わるだろう。まさか 彼（かれ）が 犯人（はんにん）だとは、夢（ゆめ）にも 思（おも）わなかった。せっかく 作（つく）った 料理（りょうり）だから、残（のこ）さず 食（た）べて ほしい。", "questions": [{"q": "Quyết tâm của người viết là gì?", "options": ["Làm qua loa cho xong", "Bỏ cuộc giữa chừng", "Kiên quyết không bỏ cuộc đến cùng", "Chờ người khác giúp"], "answer": 2, "explain": "「あくまでも最後まであきらめない」 — ～あくまでも."}, {"q": "Công việc được ước lượng tối đa bao lâu?", "options": ["Đúng 1 tuần", "Không xác định", "Ít nhất 3 ngày", "Tối đa 3 ngày"], "answer": 3, "explain": "「せいぜい３日で終わる」 — ～せいぜい = tối đa là."}, {"q": "Điều gì khiến người viết hoàn toàn bất ngờ?", "options": ["Việc anh ta đến muộn", "Việc anh ta là thủ phạm", "Việc anh ta chuyển nhà", "Việc anh ta nghỉ việc"], "answer": 1, "explain": "「まさか彼が犯人だとは」 — ～まさか (không ngờ rằng)."}, {"q": "Vì sao mong người kia ăn hết đồ ăn?", "options": ["Vì đã cất công nấu", "Vì đồ ăn rất đắt", "Vì đó là quy định", "Vì mai không ăn được nữa"], "answer": 0, "explain": "「せっかく作った料理だから」 — ～せっかく (đã cất công)."}]}}};
